import Foundation

/// 1Password などが付ける「残さないで」の印
public enum ClipboardFilter {
    public static let skipMarkers: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    public static func shouldSkip(types: [String]) -> Bool {
        types.contains { skipMarkers.contains($0) }
    }
}

public struct ClipboardEntry: Codable, Equatable, Identifiable {
    public enum Kind: String, Codable { case text, image }

    public var id: UUID
    public var kind: Kind
    public var text: String?
    /// images/ 以下のファイル名
    public var imageFile: String?
    /// "png" か "tiff"
    public var imageType: String?
    public var hash: String
    public var date: Date

    public init(id: UUID = UUID(), kind: Kind, text: String? = nil, imageFile: String? = nil, imageType: String? = nil, hash: String, date: Date) {
        self.id = id
        self.kind = kind
        self.text = text
        self.imageFile = imageFile
        self.imageType = imageType
        self.hash = hash
        self.date = date
    }
}

/// クリップボード履歴の保存。メタは history.json、画像は images/ にファイルで置く
public final class ClipboardStore {
    public static let retentionDays = 30
    public static let maxTextLength = 200_000

    public let directory: URL
    public private(set) var entries: [ClipboardEntry] = []  // 新しい順

    private var historyURL: URL { directory.appendingPathComponent("history.json") }
    public var imagesDirectory: URL { directory.appendingPathComponent("images") }

    public init(directory: URL) {
        self.directory = directory
        try? FileManager.default.createDirectory(at: imagesDirectory, withIntermediateDirectories: true)
        load()
    }

    private func load() {
        guard let data = try? Data(contentsOf: historyURL) else { return }
        let dec = JSONDecoder()
        dec.dateDecodingStrategy = .iso8601
        entries = ((try? dec.decode([ClipboardEntry].self, from: data)) ?? []).sorted { $0.date > $1.date }
    }

    private func save() {
        let enc = JSONEncoder()
        enc.dateEncodingStrategy = .iso8601
        if let data = try? enc.encode(entries) {
            try? data.write(to: historyURL, options: .atomic)
        }
    }

    public func imageURL(for entry: ClipboardEntry) -> URL? {
        entry.imageFile.map { imagesDirectory.appendingPathComponent($0) }
    }

    /// 同じ中身が既にあれば先頭へ移す
    @discardableResult
    public func addText(_ text: String, date: Date = Date()) -> ClipboardEntry? {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        let t = text.count > Self.maxTextLength ? String(text.prefix(Self.maxTextLength)) : text
        let h = "t:" + Self.fnv1a(Data(t.utf8))
        if let i = entries.firstIndex(where: { $0.hash == h }) {
            var e = entries.remove(at: i)
            e.date = date
            entries.insert(e, at: 0)
            save()
            return e
        }
        let e = ClipboardEntry(kind: .text, text: t, hash: h, date: date)
        entries.insert(e, at: 0)
        save()
        return e
    }

    @discardableResult
    public func addImage(_ data: Data, type: String, date: Date = Date()) -> ClipboardEntry? {
        guard !data.isEmpty else { return nil }
        let h = "i:" + Self.fnv1a(data)
        if let i = entries.firstIndex(where: { $0.hash == h }) {
            var e = entries.remove(at: i)
            e.date = date
            entries.insert(e, at: 0)
            save()
            return e
        }
        let id = UUID()
        let ext = type == "tiff" ? "tiff" : "png"
        let name = id.uuidString + "." + ext
        do {
            try data.write(to: imagesDirectory.appendingPathComponent(name), options: .atomic)
        } catch {
            return nil
        }
        let e = ClipboardEntry(id: id, kind: .image, imageFile: name, imageType: ext, hash: h, date: date)
        entries.insert(e, at: 0)
        save()
        return e
    }

    /// 保持期間を過ぎたものを消す。消した件数を返す
    @discardableResult
    public func prune(now: Date = Date(), retentionDays: Int = ClipboardStore.retentionDays) -> Int {
        let cutoff = now.addingTimeInterval(-Double(retentionDays) * 86400)
        let (keep, drop) = (entries.filter { $0.date >= cutoff }, entries.filter { $0.date < cutoff })
        for e in drop {
            if let url = imageURL(for: e) { try? FileManager.default.removeItem(at: url) }
        }
        // 履歴に載っていない画像ファイル（途中で落ちた残りなど）も掃除する
        let referenced = Set(keep.compactMap { $0.imageFile })
        if let files = try? FileManager.default.contentsOfDirectory(atPath: imagesDirectory.path) {
            for f in files where !referenced.contains(f) {
                try? FileManager.default.removeItem(at: imagesDirectory.appendingPathComponent(f))
            }
        }
        entries = keep
        if !drop.isEmpty { save() }
        return drop.count
    }

    public func remove(_ id: UUID) {
        guard let i = entries.firstIndex(where: { $0.id == id }) else { return }
        if let url = imageURL(for: entries[i]) { try? FileManager.default.removeItem(at: url) }
        entries.remove(at: i)
        save()
    }

    static func fnv1a(_ data: Data) -> String {
        var h: UInt64 = 0xcbf29ce484222325
        for b in data {
            h ^= UInt64(b)
            h = h &* 0x100000001b3
        }
        return String(h, radix: 16) + "-" + String(data.count)
    }
}
